export function hasFrayHeader(wasmBytes) { 
if ( ! wasmBytes || wasmBytes.length < 4) return false; 
return wasmBytes[0] === 0x46 && wasmBytes[1] === 0x52 
&& wasmBytes[2] === 0x41 && wasmBytes[3] === 0x59; 
